import json,os,statistics,subprocess
from pathlib import Path
p=Path(__file__).parent;out=p/'counter-measurements';out.mkdir()
cases=['Utf8/8192/1/nullable/array', 'Utf8/8192/3/nullable/array', 'Utf8/8192/4/nullable/array', 'Utf8/8192/1/mixed/array', 'Utf8/8192/3/mixed/array', 'Utf8/8192/4/mixed/array', 'Utf8/1/3/mixed/array', 'Utf8/8/3/nullable/array', 'Utf8/32/3/nullable/array', 'Utf8/1/3/mixed/scalar', 'Utf8/8192/3/mixed/scalar', 'Utf8/8192/3/nullable/scalar', 'Int32/8192/1/nullable/array', 'Int64/8192/1/nullable/array', 'Float32/8192/1/nullable/array', 'Float64/8192/1/nullable/array', 'Int64/1/3/nullable/array', 'Int64/8/4/nullable/array', 'Int64/8192/4/nullable/scalar', 'Float64/8192/1/nullable/scalar', 'Float32/1/3/mixed/array', 'Float64/32/3/mixed/array']
order=['before','after','after','before']*2
base=os.environ.copy();assert not any(k.startswith(('MALLOC_','GLIBC_','LD_PRELOAD','DECIMAL_BENCH_')) for k in base)
runs=[];canonical={}
for index,variant in enumerate(order):
 for ci,case in enumerate(cases[index%len(cases):]+cases[:index%len(cases)]):
  path=out/f'{index}-{variant}-{ci}';path.mkdir()
  cmd=['perf','stat','--json-output','-o',str(path/'counters.jsonl'),'-e','{instructions:u,cycles:u},task-clock:u,context-switches:u,cpu-migrations:u,page-faults:u','--','taskset','-c','2',str(p/f'{variant}-controls-bench'),str(path/'capture.json'),case]
  subprocess.run(cmd,check=True,capture_output=True,env=base,timeout=60)
  results=json.loads((path/'capture.json').read_text());assert len(results)==1 and results[0]['id']==case
  row=results[0];check={k:v for k,v in row.items() if k!='samples_ns'}
  if case not in canonical:canonical[case]=check
  else:assert canonical[case]==check
  counters=[json.loads(x) for x in (path/'counters.jsonl').read_text().splitlines() if x.startswith('{')]
  assert len(counters)==6 and all(x['pcnt-running']==100 for x in counters)
  runs.append({'index':index,'variant':variant,'case':case,'command':cmd,'results':row,'counters':counters})
 (p/'counter-performance.json').write_text(json.dumps({'order':order,'cases':cases,'runs':runs},indent=2)+'\n')
 print(index,variant,'complete',flush=True)
summary={}
for case in cases:
 stats={}
 for v in ['before','after']:
  rows=[r for r in runs if r['case']==case and r['variant']==v]
  medians=[statistics.median(r['results']['samples_ns']) for r in rows]
  instructions=[next(float(c['counter-value']) for c in r['counters'] if c['event']=='instructions:u') for r in rows]
  stats[v]={'process_medians_ns':medians,'median_ns':statistics.median(medians),'process_instructions':instructions,'median_instructions':statistics.median(instructions)}
 summary[case]=stats|{'latency_change_pct':100*(stats['after']['median_ns']/stats['before']['median_ns']-1),'instruction_change_pct':100*(stats['after']['median_instructions']/stats['before']['median_instructions']-1)}
(p/'counter-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
print('Counter checks complete',flush=True)

